#!/usr/bin/env bash
# Phase 8 Stage 2: build a reproducible datadir template containing the
# mysql.* system tables.
#
# Without it the datadir starts empty: InnoDB bootstraps its own tablespace,
# which is enough for ordinary tables, but the system tables are absent and so
# stored routines, events, named time zones and persistent index statistics do
# not work.
#
# The template is generated by running MariaDB's own bootstrap SQL through the
# embedded server, i.e. the exact code that will later read the datadir.
set -euo pipefail
ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
source "$ROOT/scripts/lib/platform.sh"

BUILD="$ROOT/build/native"
tpool_link_args "$BUILD"
LIB="$BUILD/libmysqld/libmariadbd.a"
TOOL="$BUILD/bootstrap-datadir"
STAGE="$BUILD/datadir-template"
OUT="${MARIADB_WASM_DIST:-$ROOT/dist}/datadir-template"

# Small on purpose: the template is copied into a fresh MEMFS heap for every
# runtime, so every megabyte is per-instance memory. MariaDB's default redo log
# is 96M, which would dwarf everything else in the image.
INNODB_LOG_SIZE="${INNODB_LOG_SIZE:-4M}"

# InnoDB layout. These must match what the runtime passes, or InnoDB refuses to
# start against the template ("tablespace size mismatch"), so they are asserted
# against package/src/server.ts by tests/wasm/template.test.mjs.
#
# The defaults produce 42 MB of tablespaces for ~1 MB of actual system tables:
# a 12 MB ibdata1 plus three 10 MB undo files. Folding undo back into the
# system tablespace and starting ibdata1 small brings that down by an order of
# magnitude; both still autoextend at runtime.
INNODB_DATA_FILE_PATH="${INNODB_DATA_FILE_PATH:-ibdata1:1M:autoextend}"
INNODB_UNDO_TABLESPACES="${INNODB_UNDO_TABLESPACES:-0}"

if [ ! -f "$LIB" ]; then
  echo "missing $LIB — run 10-build-native-reference.sh first" >&2
  exit 1
fi

"$HOST_CXX" -g -O1 -std=c++17 \
  -DEMBEDDED_LIBRARY -UMYSQL_CLIENT \
  -I "$ROOT/native/include" -I "$ROOT/native/src" \
  -I "$ROOT/mariadb/include" -I "$BUILD/include" \
  "$ROOT/native/src/runtime.cc" \
  "$ROOT/native/src/connection.cc" \
  "$ROOT/native/src/result.cc" \
  "$ROOT/native/src/statement.cc" \
  "$ROOT/tools/bootstrap-datadir.c" \
  "$LIB" ${TPOOL_LINK_ARGS[@]+"${TPOOL_LINK_ARGS[@]}"} \
  "${HOST_LINK_LIBS[@]}" \
  -o "$TOOL"

STATEMENTS="$BUILD/bootstrap-statements.txt"

INNODB_SQL="$BUILD/innodb-system-tables.sql"

python3 - "$ROOT/mariadb/scripts" "$STATEMENTS" <<'PY'
import pathlib, sys

scripts = pathlib.Path(sys.argv[1])
out = pathlib.Path(sys.argv[2])

# fill_help_tables.sql (~1 MB of help text) and the sys schema are deliberately
# excluded: they are large, and nothing in a test suite reads them. See
# docs/unsupported-features.md.
SOURCES = [
    "mariadb_system_tables.sql",
    "mariadb_performance_tables.sql",
    "mariadb_system_tables_data.sql",
]


def split_statements(sql: str):
    """Split on semicolons that are not inside a string, identifier or comment.

    The bootstrap SQL has no `delimiter` directives — checked, not assumed —
    so tracking quoting is sufficient. Getting this wrong would silently
    truncate a CREATE TABLE at a semicolon inside a default value."""
    statements, buffer = [], []
    quote = None
    i = 0
    while i < len(sql):
        char = sql[i]

        if quote:
            buffer.append(char)
            if char == "\\" and quote in "'\"" and i + 1 < len(sql):
                buffer.append(sql[i + 1])   # escaped char, cannot end the quote
                i += 2
                continue
            if char == quote:
                # '' inside a '-quoted string is an escaped quote, not an end.
                if i + 1 < len(sql) and sql[i + 1] == quote:
                    buffer.append(sql[i + 1])
                    i += 2
                    continue
                quote = None
            i += 1
            continue

        if char in "'\"`":
            quote = char
            buffer.append(char)
            i += 1
            continue

        if sql.startswith("--", i) and (i + 2 >= len(sql) or sql[i + 2] in " \t"):
            i = sql.find("\n", i)
            if i == -1:
                break
            continue

        if sql.startswith("/*", i):
            end = sql.find("*/", i + 2)
            i = len(sql) if end == -1 else end + 2
            continue

        if char == ";":
            statements.append("".join(buffer).strip())
            buffer = []
            i += 1
            continue

        buffer.append(char)
        i += 1

    tail = "".join(buffer).strip()
    if tail:
        statements.append(tail)
    return [s for s in statements if s]


def drop_auth_socket_block(text: str) -> str:
    lines, out, depth = text.splitlines(), [], 0
    for line in lines:
        stripped = line.strip()
        if depth == 0 and stripped.startswith("IF @auth_root_socket"):
            depth = 1
            continue
        if depth:
            if stripped.startswith("IF "):
                depth += 1
            elif stripped.startswith("END IF"):
                depth -= 1
            continue
        out.append(line)
    return "\n".join(out)


# Bootstrap mode implies the mysql database; ordinary execution does not.
collected = ["CREATE DATABASE IF NOT EXISTS mysql", "USE mysql"]

for name in SOURCES:
    text = (scripts / name).read_text()
    # mysql_install_db drops these lines for a "cross bootstrap" so the build
    # host's name is not baked in. We always do: the template has to be
    # byte-identical wherever it is generated.
    text = "\n".join(
        line for line in text.splitlines() if "@current_hostname" not in line
    )
    # The unix_socket auth setup is a compound `IF ... END IF` block, which is
    # only valid inside a routine body or in bootstrap mode's parser - split
    # into statements it is three syntax errors. Unix-socket authentication is
    # an explicit non-goal and --skip-grant-tables makes it moot, so the block
    # is removed rather than worked around.
    text = drop_auth_socket_block(text)
    collected.extend(split_statements(text))

out.write_text(
    "\n".join(s.encode().hex() for s in collected) + "\n"
)
print(f"prepared {len(collected)} statements from {len(SOURCES)} files")
PY

rm -rf "$STAGE"
mkdir -p "$STAGE"

set +e
"$TOOL" "$STAGE" "$BUILD/sql/share" "$ROOT/mariadb/sql/share/charsets" \
  "$STATEMENTS" "$INNODB_LOG_SIZE" \
  "$INNODB_DATA_FILE_PATH" "$INNODB_UNDO_TABLESPACES" "$INNODB_SQL"
BOOTSTRAP_STATUS=$?
set -e

if [ "$BOOTSTRAP_STATUS" != "0" ] && [ "$BOOTSTRAP_STATUS" != "3" ]; then
  echo "bootstrap tool failed with status $BOOTSTRAP_STATUS" >&2
  exit 1
fi

# Transient files. The redo log and the temporary tablespace are recreated on
# startup, and shipping them would make the template both larger and
# non-deterministic.
rm -f "$STAGE"/ib_logfile* "$STAGE"/ibtmp1 "$STAGE"/aria_log_control \
      "$STAGE"/aria_log.* "$STAGE"/*.err "$STAGE"/multi-master.info \
      "$STAGE"/ddl_recovery.log

# Every InnoDB tablespace, and the tables that live inside them. InnoDB
# rebuilds the shared tablespace from nothing on first start - that is how the
# templateless path has always worked - and the four system tables are
# recreated from innodb-system-tables.sql once it has. Keeping them would make
# the template roughly forty times larger for no change in behaviour.
rm -f "$STAGE"/ibdata1 "$STAGE"/undo[0-9][0-9][0-9]
python3 - "$STAGE" <<'INNODB'
import pathlib, sys

stage = pathlib.Path(sys.argv[1])
removed = []
for ibd in sorted(stage.rglob("*.ibd")):
    # Drop the .frm with it: a table description with no InnoDB dictionary
    # entry behind it is worse than no table, because MariaDB reports the
    # table as existing and then fails on access.
    frm = ibd.with_suffix(".frm")
    ibd.unlink()
    if frm.exists():
        frm.unlink()
    removed.append(ibd.stem)
print("deferred to runtime:", ", ".join(removed) or "(none)")
INNODB

cp "$INNODB_SQL" "$STAGE/innodb-system-tables.sql"

rm -rf "$OUT"
mkdir -p "$(dirname "$OUT")"
cp -R "$STAGE" "$OUT"

# Manifest: names, sizes and hashes, so a template can be told apart from a
# rebuild of a different revision.
python3 - "$OUT" <<'PY'
import hashlib, json, pathlib, sys

root = pathlib.Path(sys.argv[1])
files = {}
for path in sorted(root.rglob("*")):
    if path.is_file():
        data = path.read_bytes()
        files[str(path.relative_to(root))] = {
            "bytes": len(data),
            "sha256": hashlib.sha256(data).hexdigest(),
        }

total = sum(entry["bytes"] for entry in files.values())
(root.parent / "datadir-template.manifest.json").write_text(
    json.dumps({"totalBytes": total, "fileCount": len(files), "files": files},
               indent=2) + "\n")
print(f"template: {len(files)} files, {total / 1024 / 1024:.1f} MB")
PY

echo "DATADIR_TEMPLATE_DONE"
